import java.io.*;
import java.util.*;
public class G{
    public static void main(String[] args) {
        G app = new G();
        app.entry();
    }

    void entry() {
        InputStream is = System.in;
        OutputStream os = System.out;
        Scanner sc = new Scanner(new InputStreamReader(is));
        Formatter fmt = new Formatter(new PrintWriter(os));
        Task runner = new Task();
        runner.run(1, sc, fmt);
        fmt.flush();
        fmt.close();
    }

    static class Task {
        static class NetworkFlow {
            List<Edge>[] graph;
            Edge[][] mat;
            int[] dist;
            int V, src, sink, maxFlow;
            long minCost;
            final long INF = (long)1e15;

            NetworkFlow(int nodes, int s, int t) {
                V = nodes; src = s; sink = t;
                maxFlow = 0; minCost = 0;
                graph = new ArrayList[V];
                for(int i=0; i<V; i++) graph[i] = new ArrayList<>();
            }

            void addEdge(int u, int v, int cap, int cost) {
                Edge fwd = new Edge(v, cap, cost, graph[v].size());
                Edge bkw = new Edge(u, 0, -cost, graph[u].size());
                graph[u].add(fwd);
                graph[v].add(bkw);
            }

            void finalizeGraph() {
                mat = new Edge[V][];
                for(int i=0; i<V; i++) {
                    mat[i] = graph[i].toArray(new Edge[0]);
                    graph[i].clear();
                }
            }

            boolean bellmanFord(boolean check) {
                dist = new int[V];
                Arrays.fill(dist, Integer.MAX_VALUE / 2);
                dist[src] = 0;
                for(int iter=0; iter<V-1; iter++) {
                    boolean updated = false;
                    for(int u=0; u<V; u++) {
                        if(dist[u] == Integer.MAX_VALUE/2) continue;
                        for(Edge e : mat[u]) {
                            if(e.flow > 0 && dist[u] + e.cost < dist[e.to]) {
                                dist[e.to] = dist[u] + e.cost;
                                updated = true;
                            }
                        }
                    }
                    if(!updated) break;
                }
                if(check) {
                    for(int u=0; u<V; u++) {
                        if(dist[u] == Integer.MAX_VALUE/2) continue;
                        for(Edge e : mat[u]) {
                            if(e.flow > 0 && dist[u] + e.cost < dist[e.to]) return false;
                        }
                    }
                }
                return true;
            }

            class Edge {
                int to, flow, rev, cost;
                Edge(int t, int f, int c, int r) {to=t; flow=f; cost=c; rev=r;}
            }

            int[] parNode, parEdge, visited, distSpfa;
            int[] queueSpfa;

            boolean spfa() {
                distSpfa = new int[V];
                parNode = new int[V];
                parEdge = new int[V];
                visited = new int[V];
                queueSpfa = new int[V];
                Arrays.fill(distSpfa, Integer.MAX_VALUE/2);
                distSpfa[src] = 0;
                int head = 0, tail = 0;
                queueSpfa[tail++] = src;
                while(head != tail) {
                    int u = queueSpfa[head++];
                    if(head == V) head = 0;
                    visited[u] = 2;
                    for(int i=0; i<mat[u].length; i++) {
                        Edge e = mat[u][i];
                        if(e.flow == 0) continue;
                        int nd = distSpfa[u] + e.cost;
                        if(nd < distSpfa[e.to]) {
                            if(visited[e.to] == 0) {
                                queueSpfa[tail++] = e.to;
                                if(tail == V) tail = 0;
                            } else if(visited[e.to] == 2) {
                                if(--head == -1) head += V;
                                queueSpfa[head] = e.to;
                            }
                            visited[e.to] = 1;
                            parEdge[e.to] = i;
                            parNode[e.to] = u;
                            distSpfa[e.to] = nd;
                        }
                    }
                }
                return visited[sink] != 0;
            }

            class NodeDist implements Comparable<NodeDist> {
                int node, dist;
                NodeDist(int n, int d) {node=n; dist=d;}
                public int compareTo(NodeDist o) {return Integer.compare(dist, o.dist);}
            }

            boolean dijkstra() {
                visited = new int[V];
                distSpfa = new int[V];
                parNode = new int[V];
                parEdge = new int[V];
                Arrays.fill(distSpfa, Integer.MAX_VALUE/2);
                distSpfa[src] = 0;
                PriorityQueue<NodeDist> pq = new PriorityQueue<>();
                pq.add(new NodeDist(src, 0));
                while(!pq.isEmpty()) {
                    NodeDist cur = pq.poll();
                    while(distSpfa[cur.node] < cur.dist) {
                        if(pq.isEmpty()) return false;
                        cur = pq.poll();
                    }
                    visited[cur.node] = 2;
                    for(int i=0; i<mat[cur.node].length; i++) {
                        Edge e = mat[cur.node][i];
                        if(e.flow == 0) continue;
                        int redCost = e.cost + distSpfa[cur.node] - distSpfa[e.to];
                        int nd = cur.dist + redCost;
                        if(nd < distSpfa[e.to]) {
                            if(visited[e.to] == 2) return false;
                            pq.add(new NodeDist(e.to, nd));
                            distSpfa[e.to] = nd;
                            parNode[e.to] = cur.node;
                            parEdge[e.to] = i;
                            visited[e.to] = 1;
                        }
                    }
                }
                return visited[sink] != 0;
            }

            int augment() {
                int flow = Integer.MAX_VALUE;
                int v = sink;
                while(v != src) {
                    int u = parNode[v], idx = parEdge[v];
                    flow = Math.min(flow, mat[u][idx].flow);
                    v = u;
                }
                v = sink;
                while(v != src) {
                    int u = parNode[v], idx = parEdge[v];
                    mat[u][idx].flow -= flow;
                    mat[v][mat[u][idx].rev].flow += flow;
                    v = u;
                }
                maxFlow += flow;
                return flow;
            }

            void computeFlow() {
                bellmanFord(false);
                while(spfa()) {
                    if(distSpfa[sink] >= Integer.MAX_VALUE/2 - 1) break;
                    minCost += distSpfa[sink] * augment();
                }
            }

            void computeFlowWithPotential() {
                bellmanFord(false);
                while(dijkstra()) {
                    long m = distSpfa[sink] + distSpfa[sink] - distSpfa[src];
                    if(m >= Integer.MAX_VALUE/2L) break;
                    minCost += m * augment();
                    for(int i=0; i<V; i++) {
                        if(visited[i] != 0) {
                            distSpfa[i] += distSpfa[i] - distSpfa[src];
                        }
                    }
                }
            }
        }

        void run(int test, Scanner in, Formatter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();
            int c = in.nextInt();
            int d = in.nextInt();
            int maxLayers = n + k;
            int terminal = n * maxLayers + 1;
            NetworkFlow net = new NetworkFlow(terminal + 1, 0, terminal);
            int[] freq = new int[n + 1], items = new int[k + 1];
            for(int i = 1; i <= k; i++) {
                items[i] = in.nextInt();
                freq[items[i]]++;
            }
            for(int i = 1; i <= n; i++) {
                if(freq[i] > 0)
                    net.addEdge(0, i, freq[i], 0);
            }
            for(int i = 2; i <= n; i++) {
                for(int layer = 0; layer < maxLayers - 1; layer++) {
                    net.addEdge(layer * n + i, (layer + 1) * n + i, k, c);
                }
            }
            for(int i = 1; i <= m; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                for(int layer = 0; layer < maxLayers - 1; layer++) {
                    for(int p = 1; p <= k; p++) {
                        if(u != 1)
                            net.addEdge(layer * n + u, (layer + 1) * n + v, 1, d * (2 * p - 1) + c);
                        if(v != 1)
                            net.addEdge(layer * n + v, (layer + 1) * n + u, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for(int layer = 1; layer < maxLayers; layer++) {
                net.addEdge(layer * n + 1, terminal, k, 0);
            }
            net.finalizeGraph();
            net.computeFlowWithPotential();
            if(net.maxFlow != k)
                out.format("BUG%n");
            else
                out.format("%d%n", net.minCost);
        }
    }
}
